using System;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "OnPlayerCorruptUseBattleActionOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/OnPlayerCorruptUseBattleActionOmenData")]
public class OnPlayerCorruptUseBattleActionOmenData : OmenData
{
	private const string everyCorruptOnEnemyChantTextID = "EveryCorruptEnemyChant";

	[Header("On Player Purify Use Battle Action")]
	[SerializeField]
	private bool corruptionTimes;

	[SerializeField]
	[HideIf("corruptionTimes")]
	private OnPlayerCorruptEnemyOmenData onPlayerCorruptEnemyOmenData;

	private Action<GameObject, int> omenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = delegate(GameObject enemyTarget, int corruptAmount)
		{
			ActivateOmenWithCorruptAmount(corruptAmount);
			if (OmenAboutToTrigger())
			{
				omenInstance.PlayBlinkingFeedback();
			}
			else
			{
				omenInstance.StopBlinkingFeedback();
			}
			omenInstance.UpdateOmenCounter();
		};
		ReferenceSingleton<MiscOmensHandler>.Instance.OnPlayerCorruptEnemyOmenActions.Add(omenAction);
	}

	protected virtual void ActivateOmenWithCorruptAmount(int corruptAmount)
	{
		ActivateOmen();
	}

	private bool OmenAboutToTrigger()
	{
		return counter == TriggerAmount - 1;
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.OnPlayerCorruptEnemyOmenActions.Remove(omenAction);
	}

	public override string OmenConvertedDescription()
	{
		string actionDescription = BattleAction.GetActionDescription(ActionValue);
		return CheckAppendCounterKeptBetweenBattlesDescription(Smart.Format(base.localizationManager.GetLocalizedString("EveryCorruptEnemyChant"), TriggerAmount) + base.localizationManager.GetLocalizedSpace() + actionDescription.LowercaseFirst());
	}

	protected string GetCorruptEnemyChantWithCounterTextWithCheckCounterKept()
	{
		return CheckAppendCounterKeptBetweenBattlesDescription(base.localizationManager.GetLocalizedWhenThisCounterReaches());
	}

	protected string GetWheneverCorruptEnemyChantLocalized()
	{
		return onPlayerCorruptEnemyOmenData.GetWheneverCorruptEnemyChantLocalized() + base.localizationManager.GetLocalizedSpace();
	}
}
